import{_ as t,o as n,c as r,a3 as i}from"./chunks/framework.B5WAEDB7.js";const g=JSON.parse('{"title":"Berechnete Felder","description":"Wert übernehmen, Summe berechnen und Formel — abgeleitete Werte in ApptiveGrid.","frontmatter":{"title":"Berechnete Felder","description":"Wert übernehmen, Summe berechnen und Formel — abgeleitete Werte in ApptiveGrid."},"headers":[],"relativePath":"grids/berechnete-felder.md","filePath":"grids/berechnete-felder.md","lastUpdated":1788108473000}'),s={name:"grids/berechnete-felder.md"};function a(d,e,l,o,h,u){return n(),r("div",null,[...e[0]||(e[0]=[i(`<h1 id="berechnete-felder" tabindex="-1">Berechnete Felder <a class="header-anchor" href="#berechnete-felder" aria-label="Permalink to &quot;Berechnete Felder&quot;">​</a></h1><p>Drei Spaltentypen berechnen ihren Wert selbst, statt ihn von Hand zu erfassen:</p><table tabindex="0"><thead><tr><th>Typ</th><th>Woraus</th></tr></thead><tbody><tr><td><strong>Wert übernehmen</strong></td><td>einem verknüpften Eintrag</td></tr><tr><td><strong>Summe berechnen</strong></td><td>mehreren verknüpften Einträgen</td></tr><tr><td><strong>Formel</strong></td><td>einem Ausdruck</td></tr></tbody></table><p>Alle drei sind <strong>schreibgeschützt</strong> und stehen <strong>nicht in Formularen</strong> zur Verfügung.</p><div class="warning custom-block"><p class="custom-block-title">Zwei setzen eine Verknüpfung voraus</p><p><em>Wert übernehmen</em> und <em>Summe berechnen</em> funktionieren nur, wenn im Grid bereits eine Verknüpfung besteht. Legen Sie diese zuerst an — siehe <a href="/grids/verknuepfungen">Grids verknüpfen</a>.</p></div><hr><h2 id="wert-ubernehmen" tabindex="-1">Wert übernehmen <a class="header-anchor" href="#wert-ubernehmen" aria-label="Permalink to &quot;Wert übernehmen&quot;">​</a></h2><p>Holt einen Wert aus einem verknüpften Eintrag in das aktuelle Grid.</p><p><strong>Beispiel:</strong> Das Grid „Anmeldungen&quot; verweist über <em>Eintrag verknüpfen</em> auf „Veranstaltungen&quot;. Mit <em>Wert übernehmen</em> holen Sie das Veranstaltungsdatum direkt in die Anmeldung.</p><p><strong>Einstellungen:</strong></p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Verknüpfungsfeld</strong></td><td>Welche Verknüpfungsspalte verwendet wird</td></tr><tr><td><strong>Zielfeld</strong></td><td>Welches Feld aus dem verknüpften Eintrag geholt wird</td></tr></tbody></table><p>Der Wert aktualisiert sich automatisch. Ändert sich das Datum in „Veranstaltungen&quot;, ändert es sich in allen Anmeldungen mit.</p><div class="tip custom-block"><p class="custom-block-title">Statt zu kopieren, übernehmen</p><p>Der häufigste Anfängerfehler ist, wiederkehrende Werte in beide Grids zu schreiben. Damit laufen die Daten früher oder später auseinander. <em>Wert übernehmen</em> hält sie automatisch synchron — die Angabe existiert weiterhin nur an einer Stelle.</p></div><div class="tip custom-block"><p class="custom-block-title">Übernommene Werte sind filterbar</p><p>Ein übernommenes Datum lässt sich filtern und sortieren wie ein normales Feld. Damit bauen Sie eine Ansicht „Anmeldungen für kommende Veranstaltungen&quot;, ohne das Datum doppelt zu pflegen.</p></div><hr><h2 id="summe-berechnen" tabindex="-1">Summe berechnen <a class="header-anchor" href="#summe-berechnen" aria-label="Permalink to &quot;Summe berechnen&quot;">​</a></h2><p>Summiert ein numerisches Feld über alle verknüpften Einträge.</p><p><strong>Beispiel:</strong> Das Grid „Rechnungen&quot; verweist über <em>Mehrere Einträge verknüpfen</em> auf „Positionen&quot;. Mit <em>Summe berechnen</em> steht der Gesamtbetrag automatisch in der Rechnung.</p><p><strong>Einstellungen:</strong></p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Verknüpfungsfeld</strong></td><td>Eine Spalte vom Typ <em>Mehrere Einträge verknüpfen</em></td></tr><tr><td><strong>Zielfeld</strong></td><td>Das zu summierende numerische Feld</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Braucht die Mehrfach-Verknüpfung</p><p>Mit <em>Eintrag verknüpfen</em> funktioniert dieser Typ nicht — es gibt nichts zu summieren. Sie brauchen <strong>Mehrere Einträge verknüpfen</strong>.</p></div><p>Typische Anwendungen: Rechnungssummen, Projektaufwände, Bestellwerte, Teilnehmerzahlen.</p><hr><h2 id="formel" tabindex="-1">Formel <a class="header-anchor" href="#formel" aria-label="Permalink to &quot;Formel&quot;">​</a></h2><p>Berechnet einen Wert aus einem Ausdruck.</p><p><strong>Einstellungen:</strong></p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Ausdruck</strong></td><td>Die Berechnung, in ApptiveScript</td></tr><tr><td><strong>Ergebnistyp</strong></td><td>Welchen Typ das Ergebnis hat</td></tr></tbody></table><p>Der Editor (<em>Einen Ausdruck bearbeiten</em>) zeigt ein <strong>Beispielergebnis</strong> und den ermittelten <strong>Typ</strong>. Verlassen Sie sich dabei auf den Typ: Das Beispielergebnis bleibt bei einigen Funktionen leer, obwohl die Spalte im Betrieb rechnet — <a href="/apptivescript/editor#beispielergebnis-und-typ">warum, steht beim Ausdruckseditor</a>.</p><div class="warning custom-block"><p class="custom-block-title">Das Ergebnis muss ein anzeigbarer Wert sein</p><p>Eine Formelspalte endet immer auf einem Wert, den eine Spalte darstellen kann — Text, Zahl, Datum, Wahrheitswert. Ein Ausdruck, der ein zusammengesetztes Ergebnis liefert, lässt sich nicht anzeigen.</p><p>Zwei Fälle, in denen das auftritt — beide lassen sich mit einem angehängten Zugriff lösen:</p><table tabindex="0"><thead><tr><th>Der Ausdruck endet auf …</th><th>Anhängen</th></tr></thead><tbody><tr><td><code>parseJSON()</code> — eine Sammlung aus Schlüsseln und Werten</td><td><code>.get(&#39;&lt;Schlüssel&gt;&#39;)</code></td></tr><tr><td><code>match()</code> — eine Liste aller Treffer</td><td><code>.at(1)</code> für den ersten Treffer</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;antwort&#39;).parseJSON().get(&#39;a&#39;)</span></span>
<span class="line"><span>fieldValue(&#39;kennung&#39;).match(&#39;[a-z]&#39;).at(1)</span></span></code></pre></div></div><p>Wie ein Ausdruck aufgebaut ist, steht unter <a href="/apptivescript/schreibweise">Schreibweise</a>; wie Sie andere Felder ansprechen, unter <a href="/apptivescript/werte-referenzieren">Werte referenzieren</a>. Die vollständige Liste der Funktionen führt die <a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a>.</p><div class="tip custom-block"><p class="custom-block-title">Schrittweise entwickeln</p><p>Fangen Sie mit einem einzelnen Feld an und hängen Sie eine Funktion nach der anderen an. Der Editor zeigt nach jedem Schritt den ermittelten Typ — und damit, welche Funktionen als Nächstes möglich sind.</p></div><hr><h2 id="berechnete-felder-und-flows" tabindex="-1">Berechnete Felder und Flows <a class="header-anchor" href="#berechnete-felder-und-flows" aria-label="Permalink to &quot;Berechnete Felder und Flows&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Berechnete Felder lösen keine Flows aus</p><p>Felder vom Typ <strong>Wert übernehmen</strong>, <strong>Summe berechnen</strong> und <strong>Formel</strong> können im Flow-Auslöser <em>Eintrag wurde geändert</em> <strong>nicht</strong> als auslösendes Feld gewählt werden. Sie tauchen dort gar nicht erst auf.</p><p>Ändert sich also eine berechnete Summe, startet kein Flow.</p></div><p><strong>Der Ausweg:</strong> Reagieren Sie auf das Feld, das die Berechnung verursacht hat.</p><p>Statt „wenn sich die Rechnungssumme ändert&quot; bauen Sie den Flow auf „wenn eine Position hinzukommt&quot; — also einen Auslöser <em>Neuer Eintrag</em> im Grid „Positionen&quot;.</p><p>Dasselbe gilt für <strong>Erstellt am</strong>: auch dieses Feld steht als Bedingung nicht zur Verfügung.</p><h2 id="welcher-typ-fur-welche-aufgabe" tabindex="-1">Welcher Typ für welche Aufgabe <a class="header-anchor" href="#welcher-typ-fur-welche-aufgabe" aria-label="Permalink to &quot;Welcher Typ für welche Aufgabe&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sie wollen …</th><th>Typ</th></tr></thead><tbody><tr><td>Eine Angabe aus einem verknüpften Eintrag anzeigen</td><td><strong>Wert übernehmen</strong></td></tr><tr><td>Beträge über mehrere verknüpfte Einträge summieren</td><td><strong>Summe berechnen</strong></td></tr><tr><td>Werte innerhalb eines Eintrags verrechnen</td><td><strong>Formel</strong></td></tr><tr><td>Auf eine Änderung reagieren</td><td><strong>Flow</strong> — berechnete Felder lösen nicht aus</td></tr><tr><td>Kennzahlen über eine ganze Ansicht bilden</td><td><a href="/ansichten/filtern-sortieren-gruppieren">Gruppierung mit Aggregat</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Berechnung schlägt Automatisierung</p><p>Für abgeleitete Werte ist ein berechnetes Feld fast immer besser als ein Flow: Es aktualisiert sich sofort, verbraucht keinen Flow aus Ihrem Tarif und kann nicht fehlschlagen.</p><p>Ein Flow lohnt sich, wenn etwas <strong>passieren</strong> soll — nicht, wenn etwas nur <strong>angezeigt</strong> werden soll.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/verknuepfungen">Grids verknüpfen</a></li><li><a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></li><li><a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li></ul>`,42)])])}const p=t(s,[["render",a]]);export{g as __pageData,p as default};
